import numpy as np
import time
from math import isqrt

def construct():
    start_time = time.time()
    deadline = start_time + 110  # 10s safety margin before 120s kill
    
    # Generate powerful numbers up to a limit
    # A powerful number has the form where every prime factor appears with exponent >= 2
    # We can enumerate them as a^2 * b^3 where a is squarefree and b is any integer
    # But more practically: powerful numbers up to L can be generated by:
    # For each pair (x, y), compute x^2 * y^3, and collect unique values <= L
    # Actually, the standard way: a number is powerful iff n = a^2 * b^3 where a, b are 
    # such that the prime factorization works out. A simpler enumeration:
    # n is powerful if for every prime p | n, p^2 | n.
    # We can generate by: for each square s and cube c, n = s*c where s is a square, c is a cube,
    # and the prime factors of s and c are compatible (but actually n = a^2 * b^3 for some a, b 
    # where a is squarefree doesn't quite work either).
    #
    # Correct enumeration: every powerful number can be uniquely written as a^2 * b^3 where
    # a is squarefree? No. Let me think again.
    #
    # A powerful number n has the property that for each prime p, v_p(n) >= 2 or v_p(n) = 0.
    # We can write n = A^2 * B where A is squarefree and B is a perfect square? No.
    #
    # Actually: n = prod p_i^(e_i) where e_i >= 2. We can write e_i = 2*a_i + b_i where 
    # b_i in {0, 1} (since e_i >= 2, we can always decompose). So n = (prod p_i^(a_i))^2 * (prod p_i^(b_i))^3? 
    # No, that gives n = A^2 * B where B = prod p_i^(b_i) and b_i in {0,1}, so B is squarefree.
    # Wait: if e_i = 2*a_i + b_i with b_i in {0,1}, then n = A^2 * B where B is squarefree.
    # But that's just saying n is a square times a squarefree number, which is trivial.
    #
    # The standard characterization: n is powerful iff n = a^2 * b^3 for some integers a, b
    # where a is squarefree? No.
    #
    # Let me just use: n is powerful iff for all primes p, if p|n then p^2|n.
    # To enumerate powerful numbers up to L:
    # n = x^2 * y^3 where we need the combined prime factorization to have all exponents >= 2.
    # Actually, the cleanest way: 
    # For n = prod p^(e_p) to be powerful, e_p >= 2 for all p|n.
    # We can write n = (prod p^(floor(e_p/2)))^2 * (prod p^(e_p % 2))^3? No.
    #
    # Let me use a different approach. Generate all powerful numbers <= L by:
    # For each pair (a, b) with a >= 1, b >= 1:
    #   n = a^2 * b^3
    #   Check if n is powerful (it should be if we're careful, but let's just check)
    # Actually, a^2 * b^3 is NOT always powerful. E.g., a=2, b=3: n = 4*27 = 108 = 2^2 * 3^3. 
    # That IS powerful. a=6, b=2: n = 36*8 = 288 = 2^5 * 3^2. That's powerful too.
    # Hmm, actually I think a^2 * b^3 IS always powerful? Let's check: a = prod p^(alpha_p), b = prod p^(beta_p).
    # n = prod p^(2*alpha_p + 3*beta_p). For this to be powerful, we need 2*alpha_p + 3*beta_p >= 2 
    # for all p with 2*alpha_p + 3*beta_p > 0. Since alpha_p, beta_p >= 0 and at least one is positive,
    # 2*alpha_p + 3*beta_p >= 2*0 + 3*1 = 3 >= 2, or 2*1 + 3*0 = 2 >= 2. So yes, a^2*b^3 is always powerful!
    #
    # But not every powerful number is of the form a^2*b^3 with a, b arbitrary? 
    # Given n = prod p^(e_p) with e_p >= 2, can we write e_p = 2*alpha_p + 3*beta_p?
    # We need non-negative integers alpha_p, beta_p. Since e_p >= 2, we can always do this
    # (e.g., beta_p = e_p % 3 if that works, but e_p = 2: 2 = 2*1 + 3*0, works. e_p = 3: 3 = 2*0+3*1. 
    # e_p = 4: 4 = 2*2 + 3*0. e_p = 5: 5 = 2*1 + 3*1. e_p = 6: 6 = 2*3 or 2*0+3*2, etc.)
    # So every powerful number can be written as a^2 * b^3. But the representation is not unique.
    #
    # So to enumerate powerful numbers <= L, we can iterate over a and b such that a^2 * b^3 <= L.
    # b^3 <= L, so b <= L^(1/3). a^2 <= L / b^3, so a <= sqrt(L / b^3).
    
    # Choose L to balance number of powerful numbers and search time
    # With L = 4*10^8, we get ~43k powerful numbers (from the knowledge)
    # Let's try L = 5*10^8 to get more
    
    L = 500_000_000
    
    # Enumerate powerful numbers
    powerful = set()
    max_b = int(L ** (1/3)) + 1
    for b in range(1, max_b + 1):
        b3 = b ** 3
        if b3 > L:
            break
        max_a = isqrt(L // b3)
        for a in range(1, max_a + 1):
            n = a * a * b3
            if n <= L:
                powerful.add(n)
    
    powerful_list = sorted(powerful)
    K = len(powerful_list)
    powerful_set = set(powerful_list)
    
    # Now we want to find N (2 <= N <= 10^18) that maximizes the number of pairs (a, b) 
    # with a + b = N, a <= b, a, b powerful.
    # 
    # Key insight: if we have K powerful numbers, the number of pairs summing to N is 
    # the number of a in powerful such that N - a is also in powerful and a <= N - a.
    # 
    # We can't search all N up to 10^18. Instead, we should look at sums of two powerful numbers.
    # The sums range from 2*1 = 2 to 2*L (if L is our max powerful number).
    # But N can be up to 10^18, so we need powerful numbers up to 10^18 potentially.
    #
    # However, the task says a and b must be powerful and a + b = N with N <= 10^18.
    # So a and b can each be up to 10^18. But we can only enumerate powerful numbers up to 
    # some limit due to time constraints.
    #
    # Strategy: enumerate powerful numbers up to some limit P, then for sums N <= 2*P,
    # count the number of representations. Find the N with the most representations.
    #
    # But wait - N can be up to 10^18, and we want to maximize the count. The optimal N 
    # might be much larger than 2*P if we have powerful numbers up to P. But we can't 
    # enumerate powerful numbers up to 10^18.
    #
    # Alternative: the number of representations of N as a sum of two powerful numbers is 
    # related to the distribution. For large N, if we have powerful numbers up to M, we can 
    # only find representations where both a and b <= M. So N <= 2*M.
    #
    # To get N up to 10^18, we'd need powerful numbers up to 5*10^17. That's too many to enumerate.
    #
    # But the task just says maximize the score (number of pairs). So we should find the N 
    # (within our searchable range) that has the most pairs. The evaluator will verify the 
    # pairs are valid, so as long as our pairs are correct, the score is the count.
    #
    # So let's enumerate powerful numbers up to a reasonable limit, find the best N within 
    # [2, 2*limit], and return that.
    
    # Check time
    if time.time() > deadline - 30:
        # Not enough time, return a small result
        return {'N': 2, 'pairs': [[1, 1]]}
    
    # Use numpy to count representations for each N
    # For each pair (i, j) with i <= j, sum = powerful[i] + powerful[j]
    # Count how many times each sum appears
    
    # This is a pairwise sum problem. K can be ~50k, so K^2/2 = ~1.25 billion pairs. Too many.
    #
    # Better approach: for each N in a candidate range, count how many a in powerful_list 
    # satisfy: N - a in powerful_set and a <= N - a.
    #
    # But what range of N? N ranges from 2 to 2*L. That's up to 10^9 values. For each, 
    # we'd iterate over K powerful numbers. That's 10^9 * 50k = 5*10^13. Way too slow.
    #
    # Alternative: use convolution or FFT? The count of representations is the autocorrelation 
    # of the indicator function of powerful numbers. But the range is up to 10^9, and FFT 
    # on 10^9 points is feasible but memory-intensive (~8GB for float64).
    #
    # Let's use a smarter approach. Instead of checking all N, we can:
    # 1. Generate all pairwise sums (a, b) with a <= b, and count frequencies.
    # 2. But K^2/2 is too large for K = 50k.
    #
    # Let's reduce K. Use a smaller limit.
    # With L = 10^7, K is roughly... let's estimate. The number of powerful numbers up to x 
    # is ~ x^(2/3) / zeta(2/3) * something. Actually, the count is O(x^(2/3)).
    # For x = 10^7: ~ (10^7)^(2/3) = 10^(14/3) ~ 46415. Hmm, that's similar.
    #
    # Let me just try L = 200_000_000 and see how many powerful numbers we get, then 
    # use a sampling approach for N.
    
    # Actually, let me reconsider. The previous run with L=400M got ~43k powerful numbers 
    # and achieved score 7.267. Let me aim for similar or slightly better.
    
    # New strategy: 
    # 1. Enumerate powerful numbers up to L.
    # 2. For candidate N values, count representations.
    # 3. To find good candidates for N, note that N should be in the "middle" of the 
    #    sum range where the most pairs can contribute. The optimal N is likely around 
    #    the median of the sum distribution.
    #
    # Even better: use the fact that if we have the list of powerful numbers, the number 
    # of representations of N is the number of a in powerful_list such that N-a is in 
    # powerful_set and a <= N-a. We can precompute powerful_set for O(1) lookup.
    #
    # To find the best N, we can:
    # a) Take random samples of N and evaluate.
    # b) Use the fact that sums of two powerful numbers form a relatively dense set in 
    #    the middle range.
    #
    # Let me try: evaluate N at several candidate points and pick the best.
    
    # Actually, the most efficient approach for moderate K:
    # For each a in powerful_list, for each b in powerful_list with b >= a,
    # sum = a + b. Use a dictionary to count.
    # K = 43k, K^2/2 = ~920M. In Python, this is too slow (each iteration ~100ns, so ~92s).
    # With numpy, we can vectorize.
    
    # Use numpy: for each a, compute a + powerful_list, filter where >= a, and count.
    # But that's still K iterations, each O(K) vectorized.
    
    # Better: use np.add.reduceat or similar? Or just do it in chunks.
    
    pw = np.array(powerful_list, dtype=np.int64)
    
    # For each index i, we want to count j >= i such that pw[i] + pw[j] = N for various N.
    # This is equivalent to: for each i, the sums pw[i] + pw[j] for j >= i.
    
    # Let's use a different approach: 
    # Create an array of all pairwise sums (with i <= j) using broadcasting in chunks.
    
    # Actually, let's just do the direct approach but optimized:
    # For each i from 0 to K-1:
    #   sums = pw[i] + pw[i:]  # all sums pw[i] + pw[j] for j >= i
    #   Count frequencies of these sums
    
    # This is O(K^2) total operations but vectorized per row.
    # K = 43k, so each row has ~43k elements on average, 43k rows = ~920M total.
    # In numpy, each row operation is fast. 43k iterations, each taking ~0.5ms = ~21s. Feasible.
    
    # But memory: we can't store all sums at once. We need to use a counter.
    # Use collections.Counter or numpy histogram.
    
    # Let's use a dictionary-based approach with numpy chunks.
    
    from collections import Counter
    
    # Time check
    if time.time() > deadline - 40:
        return {'N': 2, 'pairs': [[1, 1]]}
    
    sum_counts = {}
    
    # Process in chunks to limit memory
    chunk_size = 1000
    for start in range(0, K, chunk_size):
        end = min(start + chunk_size, K)
        # For each i in [start, end), compute sums with j in [i, K)
        for i in range(start, end):
            ai = pw[i]
            # sums = ai + pw[i:]
            # We want to count each sum
            sums_chunk = ai + pw[i:]
            # Count unique sums
            # Use np.unique with return_counts
            unique_sums, counts = np.unique(sums_chunk, return_counts=True)
            for s, c in zip(unique_sums, counts):
                s_int = int(s)
                sum_counts[s_int] = sum_counts.get(s_int, 0) + int(c)
        
        # Time check within loop
        if time.time() > deadline - 20:
            break
    
    if time.time() > deadline - 10:
        if not sum_counts:
            return {'N': 2, 'pairs': [[1, 1]]}
        best_N = max(sum_counts, key=sum_counts.get)
        best_count = sum_counts[best_N]
        pairs = []
        for a in powerful_list:
            b = best_N - a
            if a <= b and b in powerful_set:
                pairs.append([a, b])
        return {'N': best_N, 'pairs': pairs}
    
    if not sum_counts:
        return {'N': 2, 'pairs': [[1, 1]]}
    
    best_N = max(sum_counts, key=sum_counts.get)
    best_count = sum_counts[best_N]
    
    # Generate pairs
    pairs = []
    for a in powerful_list:
        if a > best_N // 2:
            break
        b = best_N - a
        if b in powerful_set:
            pairs.append([a, b])
    
    return {'N': best_N, 'pairs': pairs}
